    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for name in files:
        res = extract_receipt_fields(str(img_dir / name))
        row = [name, res['date'], res['total_amount']]
        ws.append(row)
        # Ensure total_amount is stored as text (preserve trailing zeros)
        amt_cell = ws.cell(row=ws.max_row, column=3)
        if res['total_amount'] is not None:
            amt_cell.value = res['total_amount']
            amt_cell.number_format = '@'
        print(f"{name}: {res}")
    wb.save(out_path)
    print(f"Saved {out_path}")


if __name__ == '__main__':
    main()
